import unittest

from solution import build_record


class BuildRecordTests(unittest.TestCase):
    def test_exact_shape_with_empty_fields(self):
        result = build_record("Example", {})
        self.assertEqual(result, {"title": "Example", "fields": {}})
        self.assertIs(type(result), dict)
        self.assertEqual(list(result), ["title", "fields"])

    def test_nested_fields_are_deep_copied(self):
        fields = {
            "tags": ["a", {"nested": [1, 2]}],
            "metadata": {"enabled": True},
        }
        original = {
            "tags": ["a", {"nested": [1, 2]}],
            "metadata": {"enabled": True},
        }
        result = build_record("Title", fields)
        self.assertEqual(result, {"title": "Title", "fields": original})
        self.assertEqual(fields, original)

        fields["tags"][1]["nested"].append(3)
        fields["metadata"]["enabled"] = False
        self.assertEqual(result["fields"], original)

        result["fields"]["tags"][1]["nested"].append(9)
        result["fields"]["metadata"]["new"] = "value"
        self.assertNotIn(9, fields["tags"][1]["nested"])
        self.assertNotIn("new", fields["metadata"])

    def test_wrong_title_types(self):
        for title in (None, 1, True, [], {}):
            with self.subTest(title=title):
                with self.assertRaises(TypeError):
                    build_record(title, {})

    def test_empty_title_raises_value_error(self):
        with self.assertRaises(ValueError):
            build_record("", {})

    def test_wrong_fields_container_types(self):
        for fields in (None, [], (), "x", 1):
            with self.subTest(fields=fields):
                with self.assertRaises(TypeError):
                    build_record("Title", fields)

    def test_non_string_field_keys_raise_type_error(self):
        for fields in ({1: "x"}, {True: "x"}, {None: "x"}, {"ok": 1, 2: 3}):
            with self.subTest(fields=fields):
                with self.assertRaises(TypeError):
                    build_record("Title", fields)


if __name__ == "__main__":
    unittest.main()

